#include <stdio.h>
#include <stdlib.h>

typedef struct {
    long long val;
    int idx;
} Pair;

int N, Q;
long long K;
long long A[200005];
long long B[200005], C[200005];
Pair Bp[200005], Cp[200005];

int cmpPair(const void *a, const void *b) {
    const Pair *p1 = (const Pair*)a;
    const Pair *p2 = (const Pair*)b;
    if (p1->val < p2->val) return -1;
    if (p1->val > p2->val) return 1;
    return (p1->idx > p2->idx) - (p1->idx < p2->idx);
}

static inline int count_range(Pair *arr, long long V, int l, int r) {
    if (l > r) return 0;
    int lo = 0, hi = N;
    while (lo < hi) {
        int mid = (lo + hi) >> 1;
        Pair *p = &arr[mid];
        if (p->val < V || (p->val == V && p->idx < l)) lo = mid + 1;
        else hi = mid;
    }
    int left = lo;
    lo = 0; hi = N;
    while (lo < hi) {
        int mid = (lo + hi) >> 1;
        Pair *p = &arr[mid];
        if (p->val < V || (p->val == V && p->idx <= r)) lo = mid + 1;
        else hi = mid;
    }
    return lo - left;
}

static inline int count_right(int x, int L, int R) {
    if (L > R) return 0;
    int lo = L > x + 1 ? L : x + 1;
    int hi1 = R;
    long long h = (long long)x + K;
    if (h < hi1) hi1 = (int)h;
    int cnt = 0;
    if (lo <= hi1) {
        cnt += count_range(Bp, B[x] + K, lo, hi1);
    }
    int hi2 = R;
    h = (long long)x + K - 1;
    if (h < hi2) hi2 = (int)h;
    if (lo <= hi2) {
        cnt += count_range(Cp, C[x] - K, lo, hi2);
    }
    return cnt;
}

static inline int count_left(int x, int L, int R) {
    if (L > R) return 0;
    int hi = R < x - 1 ? R : x - 1;
    if (L > hi) return 0;
    int lo1 = L;
    long long h = (long long)x - K;
    if (h > lo1) lo1 = (int)h;
    int cnt = 0;
    if (lo1 <= hi) {
        cnt += count_range(Bp, B[x] - K, lo1, hi);
    }
    int lo2 = L;
    h = (long long)x - K + 1;
    if (h > lo2) lo2 = (int)h;
    if (lo2 <= hi) {
        cnt += count_range(Cp, C[x] + K, lo2, hi);
    }
    return cnt;
}

int parent[200005], sz[200005], Lbound[200005], Rbound[200005];
char active[200005];
long long total = 0;

int find(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

void add_position(int p) {
    active[p] = 1;
    parent[p] = p;
    Lbound[p] = Rbound[p] = p;
    sz[p] = 1;
    int rootL = -1, L1 = 0, R1 = 0, sizeL = 0;
    if (p > 1 && active[p - 1]) {
        rootL = find(p - 1);
        L1 = Lbound[rootL];
        R1 = Rbound[rootL];
        sizeL = sz[rootL];
        total += count_left(p, L1, R1);
    }
    int rootR = -1, L2 = 0, R2 = 0, sizeR = 0;
    if (p < N && active[p + 1]) {
        rootR = find(p + 1);
        L2 = Lbound[rootR];
        R2 = Rbound[rootR];
        sizeR = sz[rootR];
        total += count_right(p, L2, R2);
    }
    if (rootL != -1 && rootR != -1) {
        if (sizeL <= sizeR) {
            for (int x = L1; x <= R1; ++x) {
                total += count_right(x, L2, R2);
            }
        } else {
            for (int x = L2; x <= R2; ++x) {
                total += count_left(x, L1, R1);
            }
        }
    }
