        parent[rootR] = p;
        Rbound[p] = R2;
        sz[p] += sizeR;
    } else {
        Rbound[p] = p;
    }
}

int main(void) {
    scanf("%d %d %lld", &N, &Q, &K);
    for (int i = 1; i <= N; ++i) {
        scanf("%lld", &A[i]);
        B[i] = A[i] + i;
        C[i] = A[i] - i;
        Bp[i - 1].val = B[i];
        Bp[i - 1].idx = i;
        Cp[i - 1].val = C[i];
        Cp[i - 1].idx = i;
    }
    qsort(Bp, N, sizeof(Pair), cmpPair);
    qsort(Cp, N, sizeof(Pair), cmpPair);
    int D[200005];
    char deleted[200005] = {0};
    for (int i = 1; i <= Q; ++i) {
        scanf("%d", &D[i]);
        deleted[D[i]] = 1;
    }
    for (int i = 1; i <= N; ++i) {
        if (!deleted[i]) {
